//! Shu87 - turns a Shure SM58 recording into a Neumann U 87.
//!
//! Signal chain (all at 2x the host rate, see docs/MODEL.md):
//!
//!   subsonic HP -> SM58 inverse -> proximity re-map -> K87 capsule
//!   -> [low cut] -> [pad] -> FET (square law) -> FET feedback network
//!   -> output transformer (flux saturation) -> output
//!
//! The linear sections are analog prototypes generated by tools/model.py
//! from the published Shure / Neumann curves and the U 87 schematic.

mod coeffs;
mod dsp;
mod ui;

use coeffs::Section;
use dsp::{Biquad, Cascade, FetStage, HB_TAPS, OS_LATENCY, Oversampler, Transformer};
use truce::prelude64::*;
use truce_egui::EguiEditor;

// -------------------------------------------------------------- parameters

#[derive(ParamEnum, Debug)]
pub enum Pattern {
    #[name = "Cardioid"]
    Cardioid,
    #[name = "Omni"]
    Omni,
    #[name = "Figure-8"]
    Figure8,
}

#[derive(ParamEnum, Debug)]
pub enum Version {
    #[name = "U 87 Ai"]
    Ai,
    #[name = "U 87 i (1967-86)"]
    Vintage,
}

#[derive(Params)]
pub struct Shu87Params {
    #[param(id = 0, name = "Pattern")]
    pub pattern: EnumParam<Pattern>,
    #[param(id = 1, name = "Version")]
    pub version: EnumParam<Version>,
    #[param(id = 2, name = "Low Cut")]
    pub low_cut: BoolParam,
    #[param(id = 3, name = "Pad -10 dB")]
    pub pad: BoolParam,
    #[param(
        id = 4,
        name = "SM58 Distance (cm)",
        short_name = "SM58 cm",
        range = "log(1, 60)",
        default = 5.0,
        smooth = "exp(50)"
    )]
    pub sm58_dist: FloatParam,
    #[param(
        id = 5,
        name = "U87 Distance (cm)",
        short_name = "U87 cm",
        range = "log(10, 100)",
        default = 20.0,
        smooth = "exp(50)"
    )]
    pub u87_dist: FloatParam,
    #[param(
        id = 6,
        name = "Drive",
        range = "linear(-12, 18)",
        default = 0.0,
        unit = "dB",
        smooth = "exp(20)"
    )]
    pub drive: FloatParam,
    #[param(
        id = 7,
        name = "Output",
        range = "linear(-24, 24)",
        default = 0.0,
        unit = "dB",
        smooth = "exp(20)"
    )]
    pub output: FloatParam,
}

#[cfg(test)]
use Shu87ParamsParamId as P;

// ------------------------------------------------------------ chain config

/// Gradient fraction of each first-order pattern (0 = pressure, 1 = velocity).
fn gradient(p: Pattern) -> f64 {
    match p {
        Pattern::Omni => 0.0,
        Pattern::Cardioid => 0.5,
        Pattern::Figure8 => 1.0,
    }
}

/// Diaphragm sits behind the grille: SM58 ~1.5 cm behind the ball, U 87
/// ~2 cm behind the headbasket mesh. Distances are measured to the grille.
pub(crate) const SM58_GRILLE_M: f64 = 0.015;
pub(crate) const U87_GRILLE_M: f64 = 0.02;

/// 2nd-order 18 Hz Butterworth: keeps sub-audio rumble from being lifted by
/// the SM58 inverse.
pub(crate) fn subsonic() -> Section {
    let w = 2.0 * std::f64::consts::PI * 18.0;
    [1.0, 0.0, 0.0, 1.0, w * std::f64::consts::SQRT_2, w * w]
}

#[derive(Clone, Copy, PartialEq, Debug)]
struct Discrete {
    pattern: Pattern,
    version: Version,
    low_cut: bool,
}

/// One channel's complete mic model, running at the 2x rate.
#[derive(Clone, Copy)]
struct Chain {
    pattern: Pattern,
    subsonic: Cascade<1>,
    sm58: Cascade<6>,
    proximity: Biquad,
    capsule: Cascade<4>,
    low_cut: Cascade<2>,
    fet_net: Biquad,
    fet: FetStage,
    xfmr: Transformer,
}

impl Default for Chain {
    fn default() -> Self {
        Self {
            pattern: Pattern::Cardioid,
            subsonic: Cascade::default(),
            sm58: Cascade::default(),
            proximity: Biquad::default(),
            capsule: Cascade::default(),
            low_cut: Cascade::default(),
            fet_net: Biquad::default(),
            fet: FetStage::default(),
            xfmr: Transformer::default(),
        }
    }
}

impl Chain {
    fn configure(&mut self, d: Discrete, fs2: f64) {
        self.pattern = d.pattern;
        self.subsonic.set(&[subsonic()], fs2);
        self.sm58.set(&coeffs::SM58_INVERSE, fs2);
        self.capsule.set(
            match d.pattern {
                Pattern::Cardioid => &coeffs::CAPSULE_CARDIOID,
                Pattern::Omni => &coeffs::CAPSULE_OMNI,
                Pattern::Figure8 => &coeffs::CAPSULE_FIG8,
            },
            fs2,
        );
        self.low_cut.set(if d.low_cut { &coeffs::LOW_CUT } else { &[] }, fs2);
        self.fet_net.set_analog(
            match d.version {
                Version::Ai => &coeffs::FET_AI,
                Version::Vintage => &coeffs::FET_VINTAGE,
            },
            fs2,
        );
        self.fet.set_rate(fs2);
        self.xfmr.set_rate(fs2);
    }

    fn set_proximity(&mut self, sm58_cm: f64, u87_cm: f64, fs2: f64) {
        let s = dsp::proximity_section(
            0.5,
            sm58_cm / 100.0 + SM58_GRILLE_M,
            gradient(self.pattern),
            u87_cm / 100.0 + U87_GRILLE_M,
        );
        self.proximity.set_analog(&s, fs2);
    }

    fn reset(&mut self) {
        self.subsonic.reset();
        self.sm58.reset();
        self.proximity.reset();
        self.capsule.reset();
        self.low_cut.reset();
        self.fet_net.reset();
        self.fet.reset();
        self.xfmr.reset();
    }

    /// `level` = pad x drive, applied in front of the electronics and
    /// removed after them (except the pad, like the real mic).
    #[inline]
    fn run(&mut self, x: f64, level: f64, inv_drive: f64) -> f64 {
        let x = self.subsonic.run(x);
        let x = self.sm58.run(x);
        let x = self.proximity.run(x);
        let x = self.capsule.run(x);
        let x = self.low_cut.run(x);
        let x = self.fet.run(x * level);
        let x = self.fet_net.run(x);
        self.xfmr.run(x) * inv_drive
    }
}

// ------------------------------------------------------------------ plugin

const MAX_CH: usize = 2;
/// Crossfade when a switch (pattern / version / low cut) flips, so the
/// coefficient swap never clicks.
const XFADE_MS: f64 = 30.0;
/// Re-derive the proximity shelf this often (base-rate samples).
const CTRL_INTERVAL: usize = 32;

pub struct Shu87 {
    fs2: f64,
    taps: [f64; HB_TAPS],
    os: [Oversampler; MAX_CH],
    /// chains[0] is live; chains[1] is the fade target while fading.
    chains: [[Chain; 2]; MAX_CH],
    current: Discrete,
    fade_pos: usize,
    fade_len: usize,
    ctrl_count: usize,
}

impl Default for Shu87 {
    fn default() -> Self {
        Self {
            fs2: 96_000.0,
            taps: dsp::halfband_taps(),
            os: [Oversampler::default(); MAX_CH],
            chains: [[Chain::default(); 2]; MAX_CH],
            current: Discrete { pattern: Pattern::Cardioid, version: Version::Ai, low_cut: false },
            fade_pos: 0,
            fade_len: 0,
            ctrl_count: 0,
        }
    }
}

fn discrete(params: &Shu87Params) -> Discrete {
    Discrete {
        pattern: params.pattern.value(),
        version: params.version.value(),
        low_cut: params.low_cut.value(),
    }
}

impl Shu87 {
    fn fading(&self) -> bool {
        self.fade_pos < self.fade_len
    }

    fn update_proximity(&mut self, sm58_cm: f64, u87_cm: f64) {
        let fs2 = self.fs2;
        for ch in &mut self.chains {
            for c in ch.iter_mut() {
                c.set_proximity(sm58_cm, u87_cm, fs2);
            }
        }
    }

    /// A switch moved: clone the live chain (keeping its filter state, so the
    /// new branch starts "warm"), re-voice the clone and crossfade to it.
    /// If a fade is already running, the target branch is re-voiced in
    /// place and the fade simply continues - never a hard jump.
    fn begin_fade(&mut self, d: Discrete, sm58_cm: f64, u87_cm: f64) {
        let fs2 = self.fs2;
        let fading = self.fading();
        for ch in &mut self.chains {
            if !fading {
                ch[1] = ch[0];
            }
            ch[1].configure(d, fs2);
            ch[1].set_proximity(sm58_cm, u87_cm, fs2);
        }
        self.current = d;
        if !fading {
            self.fade_pos = 0;
            self.fade_len = ((XFADE_MS / 1000.0) * self.fs2) as usize;
        }
    }
}

impl PluginLogic for Shu87 {
    type Params = Shu87Params;
    type DspState = Self;

    fn reset(state: &mut Self, params: &Shu87Params, config: &AudioConfig) {
        state.fs2 = 2.0 * config.sample_rate;
        state.current = discrete(params);
        let (d, fs2) = (state.current, state.fs2);
        let (sm, u) = (params.sm58_dist.value(), params.u87_dist.value());
        for os in &mut state.os {
            os.reset();
        }
        for ch in &mut state.chains {
            for c in ch.iter_mut() {
                c.reset();
                c.configure(d, fs2);
                c.set_proximity(sm, u, fs2);
            }
        }
        state.fade_pos = 0;
        state.fade_len = 0;
        state.ctrl_count = 0;
    }

    fn latency(_state: &Self) -> u32 {
        OS_LATENCY
    }

    fn process(
        state: &mut Self,
        params: &Shu87Params,
        buffer: &mut AudioBuffer,
        _events: &EventList,
        _context: &mut ProcessContext,
    ) -> ProcessStatus {
        let n_in = buffer.num_input_channels();
        let n_ch = buffer.channels().min(MAX_CH);

        let d = discrete(params);
        if d != state.current {
            state.begin_fade(d, params.sm58_dist.value(), params.u87_dist.value());
        }

        for i in 0..buffer.num_samples() {
            let sm58_cm = params.sm58_dist.read();
            let u87_cm = params.u87_dist.read();
            let drive = db_to_linear(params.drive.read());
            let out_gain = db_to_linear(params.output.read());
            if state.ctrl_count == 0 {
                state.update_proximity(sm58_cm, u87_cm);
            }
            state.ctrl_count = (state.ctrl_count + 1) % CTRL_INTERVAL;

            let pad = if params.pad.value() { 0.316_227_766 } else { 1.0 };
            let level = pad * drive;
            let inv_drive = 1.0 / drive;

            // Fade gains for the two 2x sub-samples of this base sample.
            let mut fade = [1.0; 2];
            let fading = state.fading();
            if fading {
                for (k, g) in fade.iter_mut().enumerate() {
                    let p = ((state.fade_pos + k) as f64 / state.fade_len as f64).min(1.0);
                    // Equal-power: the two branches are highly correlated,
                    // but differ in phase near the switched corners.
                    *g = (p * std::f64::consts::FRAC_PI_2).sin();
                }
            }

            for ch in 0..n_ch {
                let src = if ch < n_in { ch } else { 0 };
                let x = if src < n_in { buffer.io(src).0[i] } else { 0.0 };
                let up = state.os[ch].upsample(x, &state.taps);
                let mut y2 = [0.0; 2];
                for k in 0..2 {
                    let a = state.chains[ch][0].run(up[k], level, inv_drive);
                    y2[k] = if fading {
                        let b = state.chains[ch][1].run(up[k], level, inv_drive);
                        let g = fade[k];
                        a * (1.0 - g * g).sqrt() + b * g
                    } else {
                        a
                    };
                }
                let y = state.os[ch].downsample(y2, &state.taps);
                buffer.io(ch).1[i] = y * out_gain;
            }

            if fading {
                state.fade_pos += 2;
                if state.fade_pos >= state.fade_len {
                    for ch in &mut state.chains {
                        ch[0] = ch[1];
                    }
                    state.fade_len = 0;
                    state.fade_pos = 0;
                }
            }
        }
        ProcessStatus::Normal
    }

    fn editor(params: Arc<Shu87Params>) -> Box<dyn Editor> {
        EguiEditor::new(params, ui::WINDOW, ui::draw).into_editor()
    }
}

truce::plugin! {
    logic: Shu87,
    params: Shu87Params,
}

truce::enable_rt_paranoid!();

